#!/usr/bin/env bash
# Benchmark v1.1 map reruns (run icde_v11) on the main folds: map v2 tiles, per-episode visible map with episode-frame
# bearings, map_ok episodes only (manifests/episode_map_v11.parquet), corrected learned-source timing.
# Order: 5- and 15-minute windows for the core methods first, then MacroTracking, then whole drives.
# Do not edit this file while it runs (bash reads scripts incrementally); write a new chain instead.
set -u
cd "$(dirname "$0")/.."
PY=${PYTHON:-python3}
W=${WORKERS:-5}
WF=${WORKERS_FULL:-3}
COMMON="--run icde_v11 --version v1.1 --manifest manifests/episode_manifest_v1.parquet --eligible-only --folds test few_shot_heldout --tiles-dir ${CANTRAJ_BENCH:-/data/backup/DriveDNA-GPS_bench}/maps/tiles_v2 --map-episodes manifests/episode_map_v11.parquet --resume --flush-min 15"
run() {
  echo "$(date '+%F %T') START $*"
  nice -n 10 ionice -c3 "$PY" scripts/run_baseline.py $COMMON "$@"
  echo "$(date '+%F %T') END rc=$? $*"
}
run --baselines map_pf_steer --group G3 --protocols O-M-Hp O-M-Hm --wins w05 w15 --workers "$W"
run --baselines map_beam_steer --group G3 --protocols F-M-Hp F-M-Hm --wins w05 w15 --workers "$W"
run --baselines macrotracking macrotracking_calib macrotracking_wrapfix --group G3 --protocols O-M-Hp --wins w05 w15 --workers "$W"
run --baselines map_pf_none --group G1 --protocols O-M-Hp O-M-Hm --wins w05 w15 --workers "$W"
run --baselines map_beam_none --group G1 --protocols F-M-Hp F-M-Hm --wins w05 w15 --workers "$W"
run --baselines map_pf_curvature --group G5 --protocols O-M-Hp O-M-Hm --wins w05 w15 --workers "$W"
run --baselines map_pf_steer --group G3 --protocols O-M-Hp O-M-Hm --wins full --workers "$WF"
run --baselines map_beam_steer --group G3 --protocols F-M-Hp F-M-Hm --wins full --workers "$WF"
run --baselines macrotracking --group G3 --protocols O-M-Hp --wins full --workers "$WF"
run --baselines map_pf_none --group G1 --protocols O-M-Hp O-M-Hm --wins full --workers "$WF"
run --baselines map_beam_none --group G1 --protocols F-M-Hp F-M-Hm --wins full --workers "$WF"
echo "$(date '+%F %T') CHAIN DONE"
